<div class="page-heading"><div><h1>Control de vencimientos</h1><p>Clasificación automática con alerta de <?=$dias?> días</p></div></div><div class="panel mb-4"><form class="row g-2"><input type="hidden" name="page" value="vencimientos"><div class="col-md-2"><select class="form-select" name="estado"><option value="todos">Todos</option><option value="proximo" <?=selected($estado,'proximo')?>>Próximos</option><option value="vencido" <?=selected($estado,'vencido')?>>Vencidos</option><option value="vigente" <?=selected($estado,'vigente')?>>Vigentes</option></select></div><div class="col-md-4"><select class="form-select" name="medicamento"><option value="">Todos los medicamentos</option><?php foreach($medicamentos as$m):?><option value="<?=$m['id']?>" <?=selected($med,$m['id'])?>><?=e($m['nombre'])?></option><?php endforeach?></select></div><div class="col-md-2"><input type="date" class="form-control" name="desde" value="<?=e($desde)?>"></div><div class="col-md-2"><input type="date" class="form-control" name="hasta" value="<?=e($hasta)?>"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filtrar</button></div></form></div><div class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Medicamento</th><th>Lote</th><th>Vencimiento</th><th>Días restantes</th><th>Cantidad</th><th>Estado</th></tr></thead><tbody><?php foreach($lotes as$l):$cond=$l['dias']<=0?'Vencido':($l['dias']<=$dias?'Próximo a vencer':'Vigente');$color=$l['dias']<=0?'danger':($l['dias']<=$dias?'warning':'success');?><tr><td><strong><?=e($l['nombre'])?></strong><small class="d-block text-muted"><?=e($l['codigo'])?></small></td><td><?=e($l['numero_lote'])?></td><td><?=date('d/m/Y',strtotime($l['fecha_vencimiento']))?></td><td><?=$l['dias']?></td><td><?=$l['cantidad_disponible']?></td><td><span class="badge text-bg-<?=$color?>"><?=$cond?></span><?php if($l['estado']==='bloqueado'):?> <span class="badge text-bg-dark">Bloqueado</span><?php endif?></td></tr><?php endforeach?><?php if(!$lotes):?><tr><td colspan="6" class="empty-state">No hay lotes para este filtro</td></tr><?php endif?></tbody></table></div></div>
